using namespace std;

template<typename T>
inline bool maxit(T& a,const T& b) {
    if(a<b) {
        a=b;
        return true;
    }
    return false;
}

template<typename T>
inline bool minit(T& a,const T& b) {
    if(a>b) {
        a=b;
        return true;
    }
    return false;
}

typedef long long LL;

inline LL gint() {
    char c=getchar();
    int f=1;
    while(c<'0'||c>'9') {
        if(c=='-') {
            f=-1;
        }
        c=getchar();
    }
    LL a=c-'0';
    while((c=getchar())>='0'&&c<='9') {
        a=a*10+c-'0';
    }
    return a*f;
}

#define MP make_pair
#define PB push_back
#define fi first
#define se second
#define foreach(it,x) for(typeof((x).begin()) it=(x).begin(),_end_=(x).end();it!=_end_;++it)
#define REP(i,n) for(int i=0,_end_=(n);i<_end_;i++)
#define FOR(i,l,r) for(int i=(l),_end_=(r);i<=_end_;i++)
#define PER(i,r,l) for(int i=(r),_beg_=(l);i>=_beg_;i--)
#define Sz(x) (int((x).size()))
#define Al(x) (x).begin(),(x).end()
#define wa(x) cerr<<#x<<" "<<x<<endl
#define _Poi const Poi&
#define _Vec const Vec&
#define _Line const Line&
#define clr(x) memset((x),0,sizeof((x)))
#define low(x) ((x)&(-(x)))
#define Ret(x,y) if(x<y)return 1; else if(x>y)return 0

const int maxk=31,MOD=int(1e9+7);

typedef int Mat[maxk][maxk];

int kb;

inline void mat_mul(Mat A,Mat B,Mat res) {
    static Mat C;
    memset(C,0,sizeof(C));
    REP(i,kb+1)REP(k,kb+1)REP(j,kb+1) {
        C[i][j]=(C[i][j]+(LL)A[i][k]*B[k][j])%MOD;
    }
    memcpy(res,C,sizeof(C));
}

Mat A[70][maxk],pre[maxk],suf[maxk],ans,I;
void init_I() {
    clr(I);
    REP(i,kb+1)I[i][i]=1;
}

int dig[70],len;

void prepocess() {
    REP(i,kb) {
        REP(j,kb+1) {
            A[0][i][j][j]=A[0][i][i][j]=1;
        }
    }
    FOR(i,1,len-1) {
        memcpy(pre[0],A[i-1][0],sizeof(A[i-1][0]));
        FOR(j,1,kb-1) {
            mat_mul(A[i-1][j],pre[j-1],pre[j]);
        }
        memcpy(suf[kb-1],A[i-1][kb-1],sizeof(A[i-1][kb-1]));
        PER(j,kb-2,0) {
            mat_mul(suf[j+1],A[i-1][j],suf[j]);
        }
        REP(j,kb) {
            mat_mul(j?pre[j-1]:I,suf[j],A[i][j]);
        }
    }
}

int main() {
    LL n=gint();
    kb=gint();
    init_I();
    while(n) {
        dig[len++]=n%kb;
        n/=kb;
    }
    prepocess();
    ans[kb][0]=1;
    int x=0;
    PER(i,len-1,0) {
        REP(j,dig[i]) {
            mat_mul(A[i][(j+x)%kb],ans,ans);
        }
        x=(x+dig[i])%kb;
    }
    int res=0;
    for(int i=0;i<kb;i++) {
        res=(res+ans[i][0])%MOD;
    }
    printf("%d\n",res+1);
    return 0;
}


